// ============================================================
// Self-contained AI blog generator (3-node pipeline)
// Fetches queue → picks topic → calls Claude → validates → outputs
// ============================================================

const QUEUE_URL = 'https://raw.githubusercontent.com/mikah33/cortisolplus-web/main/automation/topic-queue.json';
const ANTHROPIC_KEY = 'REPLACE_ANTHROPIC_KEY';
const ANTHROPIC_MODEL = 'claude-sonnet-4-5-20250929';

// --- 1. Load the topic queue ---
const queueRes = await fetch(QUEUE_URL);
if (!queueRes.ok) {
  throw new Error('Could not fetch topic queue (' + queueRes.status + '): ' + QUEUE_URL);
}
const queue = await queueRes.json();
if (!Array.isArray(queue) || queue.length === 0) {
  throw new Error('Topic queue is empty or invalid.');
}

// --- 2. Persist which topics have been used ---
const data = $getWorkflowStaticData('global');
if (!Array.isArray(data.usedSlugs)) data.usedSlugs = [];

const topic = queue.find((t) => !data.usedSlugs.includes(t.slug));
if (!topic) {
  throw new Error(`Topic queue exhausted (${queue.length} total, ${data.usedSlugs.length} already used). Add more to automation/topic-queue.json.`);
}

data.usedSlugs.push(topic.slug);

if (!topic.slug || !topic.title || !topic.primaryKeyword) {
  throw new Error('Topic queue entry is malformed: ' + JSON.stringify(topic).substring(0, 300));
}

// --- 3. Build the prompt ---
const today = new Date().toISOString().slice(0, 10);
const targetTool = topic.targetTool || '/tools/cortisol-calculator';
const internalLinks = JSON.stringify(topic.internalLinks || []);

const prompt = `You are writing a blog post for Cortisol+, an Apple Watch app that estimates cortisol from biometrics. Voice: evidence-first, no fluff, 8th-grade reading level, real science. Always include 'not medical advice; consult a healthcare provider' near the end. Cite real studies by author+year only if you are confident they exist — never invent citations.\n\nPost spec:\n- Title: ${topic.title}\n- Primary keyword (must appear in title + first 100 words): ${topic.primaryKeyword}\n- Angle: ${topic.angle || 'evidence-based explainer'}\n- Length: 900-1200 words\n- Format: MDX with YAML frontmatter\n- Internal links to weave in: ${internalLinks}\n- Target tool/quiz: ${targetTool}\n\n# Required ending structure\nSecond-to-last section: a short paragraph recommending the related test, with link to ${targetTool}.\nLast section: soft Cortisol+ app CTA — 'Cortisol+ on Apple Watch tracks the relevant biomarker continuously, so you can see if this actually moves your trend.'\nFinal line: 'Not medical advice. Consult a healthcare provider for diagnosis or treatment.'\n\nReturn ONLY the MDX (no preamble, no code fences). Start with ---. Frontmatter required: title, description (140-160 chars w/ keyword), pubDate: ${today}, tags (3-5 from cortisol/stress/sleep/hrv/supplements/perimenopause/athletes/burnout/comparisons/wearables/food), draft: false, targetTool: ${targetTool}. Structure: max 5 H2 sections, short paragraphs, at least one bulleted list.`;

// --- 4. Call Anthropic Claude ---
const claudeRes = await fetch('https://api.anthropic.com/v1/messages', {
  method: 'POST',
  headers: {
    'x-api-key': ANTHROPIC_KEY,
    'anthropic-version': '2023-06-01',
    'content-type': 'application/json'
  },
  body: JSON.stringify({
    model: ANTHROPIC_MODEL,
    max_tokens: 4096,
    messages: [{ role: 'user', content: prompt }]
  })
});

const claudeBody = await claudeRes.json();
if (!claudeRes.ok) {
  throw new Error('Claude API error (' + claudeRes.status + '): ' + JSON.stringify(claudeBody).substring(0, 500));
}

let mdx = claudeBody.content?.[0]?.text ?? '';
if (!mdx) {
  throw new Error('Claude returned empty content. Response: ' + JSON.stringify(claudeBody).substring(0, 500));
}

mdx = mdx.replace(/^```(mdx|markdown)?\s*\n/, '').replace(/\n```\s*$/, '').trim();

// --- 5. Validate ---
const errors = [];
if (!mdx.startsWith('---')) errors.push('Missing frontmatter');
if (!mdx.includes('\ntitle:')) errors.push('Missing title');
if (!mdx.includes('\ndescription:')) errors.push('Missing description');
if (!mdx.includes('\npubDate:')) errors.push('Missing pubDate');
if (!mdx.includes('draft: false')) errors.push('Missing/wrong draft flag');
if (!mdx.includes('targetTool:')) errors.push('Missing targetTool frontmatter field');
if (mdx.length < 3000) errors.push(`Too short (${mdx.length} chars)`);
if (mdx.length > 25000) errors.push(`Too long (${mdx.length} chars)`);
if (!mdx.toLowerCase().includes(topic.primaryKeyword.toLowerCase())) errors.push(`Missing keyword: ${topic.primaryKeyword}`);
if (!mdx.toLowerCase().includes('medical advice')) errors.push('Missing medical disclaimer');
if (!mdx.includes(targetTool)) errors.push(`Body missing link to targetTool: ${targetTool}`);
if (!mdx.toLowerCase().includes('cortisol+') && !mdx.toLowerCase().includes('apple watch')) errors.push('Missing Cortisol+ app mention');

if (errors.length) {
  // Un-reserve so we retry next run
  data.usedSlugs = data.usedSlugs.filter((s) => s !== topic.slug);
  throw new Error(`Validation failed for ${topic.slug}:\n${errors.join('\n')}\n\nFirst 500 chars:\n${mdx.substring(0, 500)}`);
}

// --- 6. Return for GitHub commit ---
return [{
  json: {
    slug: topic.slug,
    title: topic.title,
    primaryKeyword: topic.primaryKeyword,
    mdx,
    base64Mdx: Buffer.from(mdx, 'utf-8').toString('base64'),
    path: `src/content/blog/${topic.slug}.mdx`,
    wordCount: mdx.split(/\s+/).length
  }
}];

parameters.jsonBody:
={{ JSON.stringify({
  message: `AI post: ${$json.title} (${$json.wordCount} words)`,
  content: $json.base64Mdx,
  branch: 'main'
}) }}
